window.products.push({"id":623419,"name":"DeLonghi DCM900 10-Cup Coffee Maker","category":"homeandappliances","retail price":0.0,"sale price":null,"image":"https://m.media-amazon.com/images/I/51vDaAeLqPL._AC_SL1000_.jpg","description":"DeLonghi Coffee Maker brews 10 cups of coffee in 6 minutes and features a permanent Gold-Tone Filter that is durable and long lasting, the gold-tone filter is specially designed to keep even the finest grounds out of your coffee. This coffee maker has all the features you will need with it's pause and serve function, anti-drip system, decalcification warning light, stain resistant base, illuminated toggle switch with 2 hour automatic shut off, removable filter basket holder and with it's seamless brushed Aluminum body it will add to the Decor of any kitchen.","images":["https://m.media-amazon.com/images/I/51vDaAeLqPL._AC_SL1000_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"De'Longhi","source_asin":"B0006L9VEE","category_path":"Home & Kitchen"},"sku":"BM-623419","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B0006L9VEE","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B0006L9VEE","price_pending":true,"merchant_ready":false});
