window.products.push({"id":623972,"name":"Santa's Workshop 14\" Black and Gold King Nutcracker","category":"homeandappliances","retail price":44.98,"sale price":null,"image":"https://m.media-amazon.com/images/I/51KGdqkjd3L._AC_SL1200_.jpg","description":"Christmas is a time for lavish decoration, and this dazzling 14\" Black and Gold King Nutcracker is exactly that. Dressed in black with exquisitely detailed golden accents and trim, this king nutcracker proudly carries his golden staff and wears a golden, jeweled crown. Handcrafted from wood and hand painted, this wonderful nutcracker will provide many years of pleasure.","images":["https://m.media-amazon.com/images/I/51KGdqkjd3L._AC_SL1200_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"Santa's Workshop","source_asin":"B08DYFFS68","category_path":"Home & Kitchen"},"sku":"BM-623972","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B08DYFFS68","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B08DYFFS68","price_pending":true,"merchant_ready":false});
